<template><div class="task-page"><div class="growth-cards"><el-card><el-statistic title="应用" :value="status?.application||'-'"/></el-card><el-card><template #header>数据库</template><el-tag :type="status?.database==='UP'?'success':'danger'" size="large">{{status?.database||'UNKNOWN'}}</el-tag></el-card><el-card><template #header>Quartz 调度器</template><el-tag :type="status?.scheduler==='UP'?'success':'danger'" size="large">{{status?.scheduler||'UNKNOWN'}}</el-tag><div class="card-text">模式：{{status?.quartzMode||'-'}}</div></el-card><el-card><template #header>版本</template><div class="version-text">{{status?.version||'-'}}</div></el-card></div>
<el-row :gutter="16"><el-col :span="12"><el-card><template #header><div class="task-card-header"><span>存储空间</span><el-button size="small" @click="load">刷新</el-button></div></template><el-progress type="dashboard" :percentage="Math.round(status?.storage.usedPercent||0)" :status="status?.storage.status==='WARNING'?'exception':undefined"/><el-descriptions :column="1"><el-descriptions-item label="路径">{{status?.storage.path}}</el-descriptions-item><el-descriptions-item label="总空间">{{size(status?.storage.totalBytes)}}</el-descriptions-item><el-descriptions-item label="可用空间">{{size(status?.storage.usableBytes)}}</el-descriptions-item></el-descriptions></el-card></el-col><el-col :span="12"><el-card><template #header>部署检查清单</template><el-check-tag checked>数据库仅绑定本机</el-check-tag><el-check-tag checked>JWT 环境变量</el-check-tag><el-check-tag checked>持久化数据卷</el-check-tag><el-check-tag checked>容器健康检查</el-check-tag><el-check-tag checked>备份保留策略</el-check-tag><el-alert class="ops-alert" title="上线前仍需配置 HTTPS、防火墙和真实随机密钥" type="warning" :closable="false"/></el-card></el-col></el-row>
<el-card><template #header><div class="task-card-header"><span>备份记录</span><el-button type="primary" :loading="backing" @click="backup">立即完整备份</el-button></div></template><el-alert title="备份包含 PostgreSQL dump 和 /app/files；恢复必须在服务器终端显式确认。" type="info" :closable="false"/><el-table :data="backups"><el-table-column prop="startedAt" label="开始时间" width="180"/><el-table-column prop="backupType" label="类型" width="100"/><el-table-column label="状态" width="100"><template #default="{row}"><el-tag :type="row.status==='SUCCESS'?'success':row.status==='FAILED'?'danger':'warning'">{{row.status}}</el-tag></template></el-table-column><el-table-column prop="filePath" label="备份文件" show-overflow-tooltip/><el-table-column label="大小" width="120"><template #default="{row}">{{size(row.fileSize)}}</template></el-table-column><el-table-column prop="message" label="执行信息" show-overflow-tooltip/></el-table></el-card></div></template>
<script setup lang="ts">import{ElMessage,ElMessageBox}from'element-plus';import{onMounted,ref}from'vue';import{getSystemStatus,listBackups,runBackup,type BackupRecord,type SystemStatus}from'@/api/operations';const status=ref<SystemStatus>(),backups=ref<BackupRecord[]>([]),backing=ref(false);function size(v?:number|null){if(!v)return'-';const u=['B','KB','MB','GB','TB'];let n=v,i=0;while(n>=1024&&i<u.length-1){n/=1024;i++;}return`${n.toFixed(i?1:0)} ${u[i]}`;}async function load(){status.value=(await getSystemStatus()).data;backups.value=(await listBackups()).data;}async function backup(){await ElMessageBox.confirm('立即执行数据库和文件完整备份？','备份确认');backing.value=true;try{await runBackup();ElMessage.success('备份完成');}finally{backing.value=false;await load();}}onMounted(load);</script>